221: func (s *Store) ensureDB() error {
222: 	// Fast path: check if db is already initialized
223: 	if s.db != nil {
224: 		return nil
225: 	}
226: 
227: 	// Slow path: initialize database with lock
228: 	s.dbMu.Lock()
229: 	defer s.dbMu.Unlock()
230: 
231: 	// Double-check after acquiring lock
232: 	if s.db != nil {
233: 		return nil
234: 	}
235: 
236: 	dbPath := s.DBPath
237: 	if dbPath == "" {
238: 		dbPath = defaultDBPath
239: 	}
240: 
241: 	// Ensure directory exists
242: 	if err := os.MkdirAll(filepath.Dir(dbPath), 0o755); err != nil {
243: 		return fmt.Errorf("create db directory: %w", err)
244: 	}
245: 
246: 	database, err := newDatabase(dbPath)
247: 	if err != nil {
248: 		return fmt.Errorf("open database: %w", err)
249: 	}
250: 
251: 	// Generate device ID if needed
252: 	id, err := database.getID()
253: 	if err != nil || id == "" {
254: 		// Generate new UUID for device
255: 		u, err := uuid.NewV7()
256: 		if err == nil {
257: 			database.setID(u.String())
258: 		}
259: 	}
260: 
261: 	s.db = database
262: 
263: 	// Check if we need to migrate from config.json
264: 	migrated, err := database.isConfigMigrated()
265: 	if err != nil || !migrated {
266: 		if err := s.migrateFromConfig(database); err != nil {
267: 			slog.Warn("failed to migrate from config.json", "error", err)
268: 		}
269: 	}
270: 
271: 	// Run one-time migration from legacy airplane_mode behavior.
272: 	if err := s.migrateCloudSetting(database); err != nil {
273: 		return fmt.Errorf("migrate cloud setting: %w", err)
274: 	}
275: 
276: 	return nil
277: }
