508: // checkModelUpstream makes a HEAD request to the Ollama registry to get the upstream digest and push time
509: func (s *Server) checkModelUpstream(ctx context.Context, modelName string, timeout time.Duration) (string, int64, error) {
510: 	// Create a context with timeout for the registry check
511: 	checkCtx, cancel := context.WithTimeout(ctx, timeout)
512: 	defer cancel()
513: 
514: 	// Parse model name to get namespace, model, and tag
515: 	parts := strings.Split(modelName, ":")
516: 	name := parts[0]
517: 	tag := "latest"
518: 	if len(parts) > 1 {
519: 		tag = parts[1]
520: 	}
521: 
522: 	if !strings.Contains(name, "/") {
523: 		// If the model name does not contain a slash, assume it's a library model
524: 		name = "library/" + name
525: 	}
526: 
527: 	// Check the model in the Ollama registry using HEAD request
528: 	url := OllamaDotCom + "/v2/" + name + "/manifests/" + tag
529: 	req, err := http.NewRequestWithContext(checkCtx, "HEAD", url, nil)
530: 	if err != nil {
531: 		return "", 0, err
532: 	}
533: 
534: 	httpClient := s.httpClient()
535: 	httpClient.Timeout = timeout
536: 
537: 	resp, err := httpClient.Do(req)
538: 	if err != nil {
539: 		return "", 0, err
540: 	}
541: 	defer resp.Body.Close()
542: 
543: 	if resp.StatusCode != http.StatusOK {
544: 		return "", 0, fmt.Errorf("registry returned status %d", resp.StatusCode)
545: 	}
546: 
547: 	digest := resp.Header.Get("ollama-content-digest")
548: 	if digest == "" {
549: 		return "", 0, fmt.Errorf("no digest header found")
550: 	}
551: 
552: 	var pushTime int64
553: 	if pushTimeStr := resp.Header.Get("ollama-push-time"); pushTimeStr != "" {
554: 		if pt, err := strconv.ParseInt(pushTimeStr, 10, 64); err == nil {
555: 			pushTime = pt
556: 		}
557: 	}
558: 
559: 	return digest, pushTime, nil
560: }
