562: // isNetworkError checks if an error string contains common network/connection error patterns
563: func isNetworkError(errStr string) bool {
564: 	networkErrorPatterns := []string{
565: 		"connection refused",
566: 		"no such host",
567: 		"timeout",
568: 		"network is unreachable",
569: 		"connection reset",
570: 		"connection timed out",
571: 		"temporary failure",
572: 		"dial tcp",
573: 		"i/o timeout",
574: 		"context deadline exceeded",
575: 		"broken pipe",
576: 	}
577: 
578: 	for _, pattern := range networkErrorPatterns {
579: 		if strings.Contains(errStr, pattern) {
580: 			return true
581: 		}
582: 	}
583: 	return false
584: }
