588: func (s *Server) getError(err error) responses.ErrorEvent {
589: 	var sErr api.AuthorizationError
590: 	if errors.As(err, &sErr) && sErr.StatusCode == http.StatusUnauthorized {
591: 		return responses.ErrorEvent{
592: 			EventName: "error",
593: 			Error:     "Could not verify you are signed in. Please sign in and try again.",
594: 			Code:      "cloud_unauthorized",
595: 		}
596: 	}
597: 
598: 	errStr := err.Error()
599: 
600: 	switch {
601: 	case strings.Contains(errStr, "402"):
602: 		return responses.ErrorEvent{
603: 			EventName: "error",
604: 			Error:     "You've reached your usage limit, please upgrade to continue",
605: 			Code:      "usage_limit_upgrade",
606: 		}
607: 	case strings.HasPrefix(errStr, "pull model manifest") && isNetworkError(errStr):
608: 		return responses.ErrorEvent{
609: 			EventName: "error",
610: 			Error:     "Unable to download model. Please check your internet connection to download the model for offline use.",
611: 			Code:      "offline_download_error",
612: 		}
613: 	case errors.Is(err, ErrNetworkOffline) || strings.Contains(errStr, "operation timed out"):
614: 		return responses.ErrorEvent{
615: 			EventName: "error",
616: 			Error:     "Connection lost",
617: 			Code:      "turbo_connection_lost",
618: 		}
619: 	}
620: 	return responses.ErrorEvent{
621: 		EventName: "error",
622: 		Error:     err.Error(),
623: 	}
624: }
