65: func chatReadEnvironment(home, phase string) []string {
66: 	changes := map[string]string{
67: 		"HOME": home, "USERPROFILE": home, "LOCALAPPDATA": home,
68: 		"OLLAMA_HOST": "http://127.0.0.1:1", "OLLAMA_CORS": "false",
69: 		chatReadStageEnv: phase,
70: 	}
71: 	result := make([]string, 0, len(os.Environ())+len(changes))
72: 	for _, item := range os.Environ() {
73: 		key, _, _ := strings.Cut(item, "=")
74: 		if _, replaced := changes[key]; !replaced {
75: 			result = append(result, item)
76: 		}
77: 	}
78: 	for key, value := range changes {
79: 		result = append(result, key+"="+value)
80: 	}
81: 	return result
82: }
