332: // Raw queries preserve IDs, values and blobs independently of the production
333: // getter. Empty tables are failures, not vacuous equality proofs.
334: func chatReadSnapshot(t *testing.T, db *sql.DB) []byte {
335: 	t.Helper()
336: 	state := make(map[string][][]any)
337: 	for _, table := range []string{"chats", "messages", "attachments", "tool_calls"} {
338: 		rows, err := db.Query("SELECT * FROM " + table + " ORDER BY id")
339: 		if err != nil {
340: 			t.Fatal(err)
341: 		}
342: 		columns, err := rows.Columns()
343: 		if err != nil {
344: 			rows.Close()
345: 			t.Fatal(err)
346: 		}
347: 		for rows.Next() {
348: 			values := make([]any, len(columns))
349: 			pointers := make([]any, len(columns))
350: 			for i := range values {
351: 				pointers[i] = &values[i]
352: 			}
353: 			if err := rows.Scan(pointers...); err != nil {
354: 				rows.Close()
355: 				t.Fatal(err)
356: 			}
357: 			state[table] = append(state[table], values)
358: 		}
359: 		readErr := rows.Err()
360: 		closeErr := rows.Close()
361: 		if readErr != nil || closeErr != nil {
362: 			t.Fatalf("snapshot %s: read=%v close=%v", table, readErr, closeErr)
363: 		}
364: 		if len(state[table]) == 0 {
365: 			t.Errorf("R-03: fixture table %s unexpectedly empty", table)
366: 		}
367: 	}
368: 	return []byte(mustChatReadJSON(t, state))
369: }"}

