668: func (s *Server) chat(w http.ResponseWriter, r *http.Request) error {
669: 	w.Header().Set("Content-Type", "text/jsonl")
670: 	w.Header().Set("Cache-Control", "no-cache")
671: 	w.Header().Set("Connection", "keep-alive")
672: 	w.Header().Set("Transfer-Encoding", "chunked")
673: 
674: 	flusher, ok := w.(http.Flusher)
675: 	if !ok {
676: 		return errors.New("streaming not supported")
677: 	}
678: 
679: 	if r.Method != "POST" {
680: 		return not.Found
681: 	}
682: 
683: 	cid := r.PathValue("id")
684: 	createdChat := false
685: 
686: 	// if cid is the literal string "new", then we create a new chat before
687: 	// performing our normal actions
688: 	if cid == "new" {
689: 		u, err := uuid.NewV7()
690: 		if err != nil {
691: 			return fmt.Errorf("failed to generate new chat id: %w", err)
692: 		}
693: 		cid = u.String()
694: 		createdChat = true
695: 	}
696: 
697: 	var req responses.ChatRequest
698: 	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
699: 		fmt.Fprintf(os.Stderr, "error unmarshalling body: %v\n", err)
700: 		return fmt.Errorf("invalid request body: %w", err)
701: 	}
702: 
703: 	if req.Model == "" {
704: 		return fmt.Errorf("empty model")
705: 	}
706: 
707: 	// Don't allow empty messages unless forceUpdate is true
708: 	if req.Prompt == "" && !req.ForceUpdate {
709: 		return fmt.Errorf("empty message")
710: 	}
711: 
712: 	if createdChat {
713: 		// send message to the client that the chat has been created
714: 		json.NewEncoder(w).Encode(responses.ChatEvent{
715: 			EventName: "chat_created",
716: 			ChatID:    &cid,
717: 		})
718: 		flusher.Flush()
719: 	}
720: 
721: 	// Check if this is from a specific message index (e.g. for editing)
722: 	idx := -1
723: 	if req.Index != nil {
724: 		idx = *req.Index
725: 	}
726: 
727: 	// Load chat with attachments since we need them for processing
728: 	chat, err := s.Store.ChatWithOptions(cid, true)
729: 	if err != nil {
730: 		if !errors.Is(err, not.Found) {
731: 			return err
732: 		}
733: 		chat = store.NewChat(cid)
734: 	}
735: 
736: 	// Only add user message if not forceUpdate
737: 	if !req.ForceUpdate {
738: 		var messageOptions *store.MessageOptions
739: 		if len(req.Attachments) > 0 {
740: 			storeAttachments := make([]store.File, 0, len(req.Attachments))
741: 
742: 			for _, att := range req.Attachments {
743: 				if att.Data == "" {
744: 					// This is an existing file reference - keep it from the original message
745: 					if idx >= 0 && idx < len(chat.Messages) {
746: 						originalMessage := chat.Messages[idx]
747: 						// Find the file by filename in the original message
748: 						for _, originalFile := range originalMessage.Attachments {
749: 							if originalFile.Filename == att.Filename {
750: 								storeAttachments = append(storeAttachments, originalFile)
751: 								break
752: 							}
753: 						}
754: 					}
755: 				} else {
756: 					// This is a new file - decode base64 data
757: 					data, err := base64.StdEncoding.DecodeString(att.Data)
758: 					if err != nil {
759: 						s.log().Error("failed to decode attachment data", "error", err, "filename", att.Filename)
760: 						continue
761: 					}
762: 
763: 					storeAttachments = append(storeAttachments, store.File{
764: 						Filename: att.Filename,
765: 						Data:     data,
766: 					})
767: 				}
768: 			}
769: 
770: 			messageOptions = &store.MessageOptions{
771: 				Attachments: storeAttachments,
772: 			}
773: 		}
774: 		userMsg := store.NewMessage("user", req.Prompt, messageOptions)
775: 
776: 		if idx >= 0 && idx < len(chat.Messages) {
777: 			// Generate from specified message: truncate and replace
778: 			chat.Messages = chat.Messages[:idx]
779: 			chat.Messages = append(chat.Messages, userMsg)
780: 		} else {
781: 			// Normal mode: append new message
782: 			chat.Messages = append(chat.Messages, userMsg)
783: 		}
784: 
785: 		if err := s.Store.SetChat(*chat); err != nil {
786: 			return err
787: 		}
788: 	}
789: 
790: 	ctx, cancel := context.WithCancel(r.Context())
791: 	defer cancel()
792: 
793: 	_, cancelLoading := context.WithCancel(ctx)
794: 	loading := false
795: 
796: 	c := s.inferenceClient()
797: 
798: 	// Check if the model exists locally by trying to show it
799: 	// TODO (jmorganca): skip this round trip and instead just act
800: 	// on a 404 error on chat
801: 	_, err = c.Show(ctx, &api.ShowRequest{Model: req.Model})
802: 	if err != nil || req.ForceUpdate {
803: 		// Create an empty assistant message to store the model information
804: 		// This will be overwritten when the model responds
805: 		chat.Messages = append(chat.Messages, store.NewMessage("assistant", "", &store.MessageOptions{Model: req.Model}))
806: 		if err := s.Store.SetChat(*chat); err != nil {
807: 			cancelLoading()
808: 			return err
809: 		}
810: 		// Send download progress events while the model is being pulled
811: 		// TODO (jmorganca): this only shows the largest digest, but we
812: 		// should show the progress for the total size of the download
813: 		var largestDigest string
814: 		var largestTotal int64
815: 
816: 		err = c.Pull(ctx, &api.PullRequest{Model: req.Model}, func(progress api.ProgressResponse) error {
817: 			if progress.Digest != "" && progress.Total > largestTotal {
818: 				largestDigest = progress.Digest
819: 				largestTotal = progress.Total
820: 			}
821: 
822: 			if progress.Digest != "" && progress.Digest == largestDigest {
823: 				progressEvent := responses.DownloadEvent{
824: 					EventName: string(EventDownload),
825: 					Total:     progress.Total,
826: 					Completed: progress.Completed,
827: 					Done:      false,
828: 				}
829: 
830: 				if err := json.NewEncoder(w).Encode(progressEvent); err != nil {
831: 					return err
832: 				}
833: 				flusher.Flush()
834: 			}
835: 			return nil
836: 		})
837: 		if err != nil {
838: 			s.log().Error("model download error", "error", err, "model", req.Model)
839: 			errorEvent := s.getError(err)
840: 			json.NewEncoder(w).Encode(errorEvent)
841: 			flusher.Flush()
842: 			cancelLoading()
843: 			return fmt.Errorf("failed to download model: %w", err)
844: 		}
845: 
846: 		if err := json.NewEncoder(w).Encode(responses.DownloadEvent{
847: 			EventName: string(EventDownload),
848: 			Completed: largestTotal,
849: 			Total:     largestTotal,
850: 			Done:      true,
851: 		}); err != nil {
852: 			cancelLoading()
853: 			return err
854: 		}
855: 		flusher.Flush()
856: 
857: 		// If forceUpdate, we're done after updating the model
858: 		if req.ForceUpdate {
859: 			json.NewEncoder(w).Encode(responses.ChatEvent{EventName: "done"})"}

