61: // R-01/R-02: the header is present and the recorded message reaches Scan.
62: func TestChatReadRejectsMalformedMessage(t *testing.T) {
63: 	s, cleanup := setupTestStore(t)
64: 	t.Cleanup(cleanup)
65: 	want := NewChat("malformed-chat")
66: 	want.Messages = []Message{NewMessage("user", "original message", nil)}
67: 	if err := s.SetChat(*want); err != nil {
68: 		t.Fatal(err)
69: 	}
70: 	result, err := s.db.conn.Exec("UPDATE messages SET stream = 'invalid_boolean' WHERE chat_id = ?", want.ID)
71: 	if err != nil {
72: 		t.Fatal(err)
73: 	}
74: 	n, err := result.RowsAffected()
75: 	if err != nil || n != 1 {
76: 		t.Fatalf("fault affected %d rows: %v", n, err)
77: 	}
78: 	var headerID, rawValue string
79: 	if err := s.db.conn.QueryRow("SELECT id FROM chats WHERE id = ?", want.ID).Scan(&headerID); err != nil || headerID != want.ID {
80: 		t.Fatalf("original header missing: id=%q err=%v", headerID, err)
81: 	}
82: 	if err := s.db.conn.QueryRow("SELECT stream FROM messages WHERE chat_id = ?", want.ID).Scan(&rawValue); err != nil || rawValue != "invalid_boolean" {
83: 		t.Fatalf("fault value not delivered: value=%q err=%v", rawValue, err)
84: 	}
85: 	for _, attachments := range []bool{false, true} {
86: 		got, err := s.ChatWithOptions(want.ID, attachments)
87: 		if got != nil || err == nil {
88: 			t.Fatalf("R-01: malformed message returned success: %#v", got)
89: 		}
90: 		if errors.Is(err, not.Found) || errors.Is(err, sql.ErrNoRows) {
91: 			t.Errorf("R-01: scan failure became absence: %v", err)
92: 		}
93: 		if errors.Unwrap(err) == nil || !strings.Contains(err.Error(), "scan message:") {
94: 			t.Errorf("R-02: scan failure lost its cause/context: %v", err)
95: 		}
96: 	}
97: }
