718: func (db *database) saveChat(chat Chat) error {
719: 	tx, err := db.conn.Begin()
720: 	if err != nil {
721: 		return fmt.Errorf("begin transaction: %w", err)
722: 	}
723: 	defer tx.Rollback()
724: 
725: 	// Use COALESCE for browser_state to avoid wiping an existing
726: 	// chat-level browser_state when saving a chat that doesn't include a new state payload.
727: 	// Many code paths call SetChat to update metadata/messages only; without COALESCE the
728: 	// UPSERT would overwrite browser_state with NULL, breaking revisit rendering that relies
729: 	// on the last persisted full tool state.
730: 	query := `
731: 		INSERT INTO chats (id, title, created_at, browser_state)
732: 		VALUES (?, ?, ?, ?)
733: 		ON CONFLICT(id) DO UPDATE SET
734: 			title = excluded.title,
735: 			browser_state = COALESCE(excluded.browser_state, chats.browser_state)
736: 	`
737: 
738: 	var browserState sql.NullString
739: 	if chat.BrowserState != nil {
740: 		browserState = sql.NullString{String: string(chat.BrowserState), Valid: true}
741: 	}
742: 
743: 	_, err = tx.Exec(query,
744: 		chat.ID,
745: 		chat.Title,
746: 		chat.CreatedAt,
747: 		browserState,
748: 	)
749: 	if err != nil {
750: 		return fmt.Errorf("save chat: %w", err)
751: 	}
752: 
753: 	// Delete existing messages (we'll re-insert all)
754: 	_, err = tx.Exec("DELETE FROM messages WHERE chat_id = ?", chat.ID)
755: 	if err != nil {
756: 		return fmt.Errorf("delete messages: %w", err)
757: 	}
758: 
759: 	// Insert messages
760: 	for _, msg := range chat.Messages {
761: 		messageID, err := db.insertMessage(tx, chat.ID, msg)
762: 		if err != nil {
763: 			return fmt.Errorf("insert message: %w", err)
764: 		}
765: 
766: 		// Insert tool calls if any
767: 		for _, toolCall := range msg.ToolCalls {
768: 			err := db.insertToolCall(tx, messageID, toolCall)
769: 			if err != nil {
770: 				return fmt.Errorf("insert tool call: %w", err)
771: 			}
772: 		}
773: 	}
774: 
775: 	return tx.Commit()
776: }
