798: func (db *database) updateLastMessage(chatID string, msg Message) error {
799: 	tx, err := db.conn.Begin()
800: 	if err != nil {
801: 		return fmt.Errorf("begin transaction: %w", err)
802: 	}
803: 	defer tx.Rollback()
804: 
805: 	// Get the ID of the last message
806: 	var messageID int64
807: 	err = tx.QueryRow(`
808: 		SELECT MAX(id) FROM messages WHERE chat_id = ?
809: 	`, chatID).Scan(&messageID)
810: 	if err != nil {
811: 		return fmt.Errorf("get last message id: %w", err)
812: 	}
813: 
814: 	query := `
815: 		UPDATE messages 
816: 		SET content = ?, thinking = ?, model_name = ?, updated_at = ?, thinking_time_start = ?, thinking_time_end = ?, tool_result = ?
817: 		WHERE id = ?
818: 	`
819: 
820: 	var thinkingTimeStart, thinkingTimeEnd sql.NullTime
821: 	if msg.ThinkingTimeStart != nil {
822: 		thinkingTimeStart = sql.NullTime{Time: *msg.ThinkingTimeStart, Valid: true}
823: 	}
824: 	if msg.ThinkingTimeEnd != nil {
825: 		thinkingTimeEnd = sql.NullTime{Time: *msg.ThinkingTimeEnd, Valid: true}
826: 	}
827: 
828: 	var modelName sql.NullString
829: 	if msg.Model != "" {
830: 		modelName = sql.NullString{String: msg.Model, Valid: true}
831: 	}
832: 
833: 	var toolResultJSON sql.NullString
834: 	if msg.ToolResult != nil {
835: 		resultBytes, err := json.Marshal(msg.ToolResult)
836: 		if err != nil {
837: 			return fmt.Errorf("marshal tool result: %w", err)
838: 		}
839: 		toolResultJSON = sql.NullString{String: string(resultBytes), Valid: true}
840: 	}
841: 
842: 	result, err := tx.Exec(query,
843: 		msg.Content,
844: 		msg.Thinking,
845: 		modelName,
846: 		msg.UpdatedAt,
847: 		thinkingTimeStart,
848: 		thinkingTimeEnd,
849: 		toolResultJSON,
850: 		messageID,
851: 	)
852: 	if err != nil {
853: 		return fmt.Errorf("update last message: %w", err)
854: 	}
855: 
856: 	rowsAffected, err := result.RowsAffected()
857: 	if err != nil {
858: 		return fmt.Errorf("get rows affected: %w", err)
859: 	}
860: 	if rowsAffected == 0 {
861: 		return fmt.Errorf("no message found to update")
862: 	}
863: 
864: 	_, err = tx.Exec("DELETE FROM attachments WHERE message_id = ?", messageID)
865: 	if err != nil {
866: 		return fmt.Errorf("delete existing attachments: %w", err)
867: 	}
868: 	for _, att := range msg.Attachments {
869: 		err := db.insertAttachment(tx, messageID, att)
870: 		if err != nil {
871: 			return fmt.Errorf("insert attachment: %w", err)
872: 		}
873: 	}
874: 
875: 	_, err = tx.Exec("DELETE FROM tool_calls WHERE message_id = ?", messageID)
876: 	if err != nil {
877: 		return fmt.Errorf("delete existing tool calls: %w", err)
878: 	}
879: 	for _, toolCall := range msg.ToolCalls {
880: 		err := db.insertToolCall(tx, messageID, toolCall)
881: 		if err != nil {
882: 			return fmt.Errorf("insert tool call: %w", err)
883: 		}
884: 	}
885: 
886: 	return tx.Commit()
887: }
