912: func (db *database) getMessages(chatID string, loadAttachmentData bool) ([]Message, error) {
913: 	query := `
914: 		SELECT id, role, content, thinking, stream, model_name, created_at, updated_at, thinking_time_start, thinking_time_end, tool_result
915: 		FROM messages
916: 		WHERE chat_id = ?
917: 		ORDER BY id ASC
918: 	`
919: 
920: 	rows, err := db.conn.Query(query, chatID)
921: 	if err != nil {
922: 		return nil, fmt.Errorf("query messages: %w", err)
923: 	}
924: 	defer rows.Close()
925: 
926: 	var messages []Message
927: 	for rows.Next() {
928: 		var msg Message
929: 		var messageID int64
930: 		var thinkingTimeStart, thinkingTimeEnd sql.NullTime
