994: func (db *database) insertMessage(tx *sql.Tx, chatID string, msg Message) (int64, error) {
995: 	query := `
996: 		INSERT INTO messages (chat_id, role, content, thinking, stream, model_name, created_at, updated_at, thinking_time_start, thinking_time_end, tool_result)
997: 		VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
998: 	`
999: 
1000: 	var thinkingTimeStart, thinkingTimeEnd sql.NullTime
1001: 	if msg.ThinkingTimeStart != nil {
1002: 		thinkingTimeStart = sql.NullTime{Time: *msg.ThinkingTimeStart, Valid: true}
1003: 	}
1004: 	if msg.ThinkingTimeEnd != nil {
1005: 		thinkingTimeEnd = sql.NullTime{Time: *msg.ThinkingTimeEnd, Valid: true}
1006: 	}
1007: 
1008: 	var modelName sql.NullString
1009: 	if msg.Model != "" {
1010: 		modelName = sql.NullString{String: msg.Model, Valid: true}
1011: 	}
1012: 
1013: 	var toolResultJSON sql.NullString
1014: 	if msg.ToolResult != nil {
1015: 		resultBytes, err := json.Marshal(msg.ToolResult)
1016: 		if err != nil {
1017: 			return 0, fmt.Errorf("marshal tool result: %w", err)
1018: 		}
1019: 		toolResultJSON = sql.NullString{String: string(resultBytes), Valid: true}
1020: 	}
1021: 
1022: 	result, err := tx.Exec(query,
1023: 		chatID,
1024: 		msg.Role,
1025: 		msg.Content,
1026: 		msg.Thinking,
1027: 		msg.Stream,
1028: 		modelName,
1029: 		msg.CreatedAt,
1030: 		msg.UpdatedAt,
1031: 		thinkingTimeStart,
1032: 		thinkingTimeEnd,
1033: 		toolResultJSON,
1034: 	)
1035: 	if err != nil {
1036: 		return 0, err
1037: 	}
1038: 
1039: 	messageID, err := result.LastInsertId()
1040: 	if err != nil {
1041: 		return 0, err
1042: 	}
1043: 
1044: 	for _, att := range msg.Attachments {
1045: 		err := db.insertAttachment(tx, messageID, att)
1046: 		if err != nil {
1047: 			return 0, fmt.Errorf("insert attachment: %w", err)
1048: 		}
1049: 	}
1050: 
1051: 	return messageID, nil
1052: }
