1054: func (db *database) getAttachments(messageID int64, loadData bool) ([]File, error) {
1055: 	var query string
1056: 	if loadData {
1057: 		query = `
1058: 			SELECT filename, data
1059: 			FROM attachments
1060: 			WHERE message_id = ?
1061: 			ORDER BY id ASC
1062: 		`
1063: 	} else {
1064: 		query = `
1065: 			SELECT filename, '' as data
1066: 			FROM attachments
1067: 			WHERE message_id = ?
1068: 			ORDER BY id ASC
1069: 		`
1070: 	}
1071: 
1072: 	rows, err := db.conn.Query(query, messageID)
1073: 	if err != nil {
1074: 		return nil, fmt.Errorf("query attachments: %w", err)
1075: 	}
1076: 	defer rows.Close()
1077: 
1078: 	var attachments []File
1079: 	for rows.Next() {
1080: 		var file File
1081: 		err := rows.Scan(&file.Filename, &file.Data)
1082: 		if err != nil {
1083: 			return nil, fmt.Errorf("scan attachment: %w", err)
1084: 		}
1085: 		attachments = append(attachments, file)
1086: 	}
1087: 
1088: 	if err := rows.Err(); err != nil {
1089: 		return nil, fmt.Errorf("iterate attachments: %w", err)
1090: 	}
1091: 
1092: 	return attachments, nil
1093: }
